import { establishmentAddress } from './marketplace-settings.js';
import { resolveSelection } from './product-types.js';
import { readDeliveryLocation, localFreightQuote } from './delivery-context.js';
import { currentBuyer, ownsBuyerOrder } from './buyer-account.js';
import { createBuyerAccountUI } from './buyer-account-ui.js';
import { reorderLines } from './reorder.js';
import { readMarketplace, sellerContext, auditMarketplace, pickupAllowed } from './marketplace-settings.js';
import { ORDER_STORES, ORDER_STATUS, statusLabel, orderEvent, createDemoOrder, changeDemoPayment, advanceDemoSuborder, validateOrderStock } from './order-model.js';
import { readDemoOrders, saveDemoOrders } from './order-storage.js';
const orderEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const orderMoney=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(c/100);
const orderDate=s=>new Date(s).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'});
const methodLabel=m=>({delivery:'Entrega pela loja',pickup:'Retirada na loja',digital:'Download digital'}[m]);
function orderItems(items){return items.map(i=>`<div class="order-item"><div><b>${i.qty}× ${orderEscape(i.name)}</b>${i.parts.length?`<ul>${i.parts.map(p=>`<li>${p.qty}× ${orderEscape(p.name)}${p.label?' · '+orderEscape(p.label):''}</li>`).join('')}</ul>`:i.label?`<small>${orderEscape(i.label)}</small>`:''}</div><strong>${orderMoney(i.totalCents)}</strong></div>`).join('');}
function orderSummary(s){return `<div class="order-totals"><span>Produtos <b>${orderMoney(s.subtotal)}</b></span><span>${s.method==='digital'?'Sem frete':methodLabel(s.method)} <b>${orderMoney(s.freight)}</b></span>${s.discount?`<span>Desconto <b>− ${orderMoney(s.discount)}</b></span>`:''}<span>Total da loja <b>${orderMoney(s.total)}</b></span></div>`;}
function orderDownloads(order,s){return s.items.filter(i=>i.type==='virtual').map(i=>`<button class="btn secondary" data-order-action="download" data-order="${order.id}" data-sub="${s.id}" data-product="${i.id}" ${order.payment==='paid'?'':'disabled'}>${order.payment==='paid'?'Baixar exemplo (.txt)':'Download bloqueado'} · ${orderEscape(i.name)}</button>`).join('');}
export function ordersMarkup(role='buyer',detailId=null){
  const orders=readDemoOrders().filter(o=>(role!=='buyer'||ownsBuyerOrder(o))&&(role!=='seller'||o.suborders.some(s=>s.store===sellerContext()))&&(!detailId||o.id===detailId));
  if(role==='buyer'&&!detailId)return `<div class="order-workspace"><button class="text-link" data-buyer-account>← Minha conta</button><p>Suas compras neste navegador. Novas compras usam preço e disponibilidade atuais.</p>${orders.length?orders.slice().reverse().map(o=>`<article class="order-list-card"><header><div><b>${orderEscape(o.id)}</b><p>${orderDate(o.createdAt)}</p></div><strong>${orderMoney(o.total)}</strong></header><p>${o.suborders.map(s=>orderEscape(s.storeName)+' · '+statusLabel(s)).join('<br>')}</p><div class="order-list-actions"><button class="btn secondary" data-buyer-detail="${o.id}">Ver pedido</button><button class="btn" data-buyer-reorder="${o.id}">Comprar novamente</button></div></article>`).join(''):'<div class="order-empty"><h3>Você ainda não fez pedidos.</h3><p>Explore os produtos e finalize sua primeira compra demonstrativa.</p></div>'}<p id="order-feedback" role="status"></p></div>`;
  return `<div class="order-workspace">${role==='buyer'?'<button class="text-link" data-buyer-detail="">← Voltar aos pedidos</button>':''}<p class="order-notice">Demonstração local • Sem cobrança ou envio real. Pedidos e conversas ficam neste navegador. Use somente dados fictícios.</p>${orders.length?orders.slice().reverse().map(o=>`<article class="purchase-card"><header><div><span class="eyebrow">${orderEscape(o.id)}${o.demoData?' · PEDIDO FICTÍCIO':''}</span><h3>${o.payment==='pending'?'Aguardando pagamento':ORDER_STATUS[o.payment]}</h3><small>${orderDate(o.createdAt)} · ${o.paymentMethod==='pix'?'Pix':'Cartão de crédito'}</small></div>${role==='buyer'?`<div><strong>${orderMoney(o.total)}</strong><button class="btn secondary" data-buyer-reorder="${o.id}">Comprar novamente</button></div>`:''}</header>${role==='buyer'&&o.billingAddress?`<details class="order-history"><summary>Endereço de cobrança deste pedido</summary><p>${orderEscape(o.billingAddress.name)} · ${orderEscape(o.billingAddress.street)}, ${orderEscape(o.billingAddress.number)}<br>${orderEscape(o.billingAddress.city)} · CEP ${orderEscape(o.billingAddress.cep)}</p></details>`:''}${role==='buyer'&&o.payment!=='paid'?`<div class="payment-simulator"><p>${o.payment==='failed'?'Pagamento não aprovado. Você pode tentar novamente.':'Pedido criado. Aguardando confirmação demonstrativa.'} Nenhuma chave Pix ou cartão real é necessário.</p><button class="btn" data-order-action="pay" data-result="paid" data-order="${o.id}">Simular pagamento aprovado</button><button class="text-link" data-order-action="pay" data-result="failed" data-order="${o.id}">Simular falha</button></div>`:''}${o.suborders.filter(s=>role!=='seller'||s.store===sellerContext()).map(s=>`<section class="suborder-card"><div class="suborder-heading"><div><h3>${orderEscape(s.storeName)}</h3><small>${orderEscape(s.id)} · ${methodLabel(s.method)}</small></div><span class="type-pill">${statusLabel(s)}${s.hold?' · Em análise':''}</span></div>${orderItems(s.items)}${orderSummary(s)}${s.method==='delivery'?`<p class="order-address">${orderEscape(o.address.name)} · ${orderEscape(o.address.street)}, ${orderEscape(o.address.number)} · ${orderEscape(o.address.city)} · CEP ${orderEscape(o.address.cep)}<br>${orderEscape(o.address.complement||'')}<br>Trajeto informado para simulação: ${s.km} km. Tarifa: ${orderMoney(s.rate??ORDER_STORES[s.store]?.rate??0)}/km.</p>`:s.method==='pickup'?`<p class="order-address">Retirada: ${orderEscape(establishmentAddress(s.establishment))}. Aguarde “Pronto para retirada”.</p>`:''}${s.dispatchBy?`<p class="dispatch-note">${s.method==='pickup'?'Preparação para retirada':'Despacho'} até ${s.dispatchBy.split('-').reverse().join('/')}${role!=='buyer'?' · corte '+s.cutoff:''}. Calendário demonstrativo: segunda a sexta, sem feriados configurados. ${s.method==='delivery'?'Prazo de chegada ainda não estimado; regra global por distância pendente.':''}</p>`:''}<details class="order-history"><summary>Acompanhar etapas</summary><ol>${s.history.map(h=>`<li>${statusLabel(s,h.status)} <small>${orderDate(h.at)}</small></li>`).join('')}</ol></details><div class="order-actions">${role!=='buyer'&&o.payment==='paid'&&s.physical&&!['completed','cancelled'].includes(s.status)?`<button class="btn" data-order-action="advance" data-order="${o.id}" data-sub="${s.id}">${{paid:'Iniciar preparação',preparing:s.method==='pickup'?'Marcar pronto para retirada':'Marcar pronto para envio',shipping:'Confirmar saída para entrega',ready:'Confirmar retirada',dispatched:'Confirmar entrega'}[s.status]}</button>`:''}${role==='admin'?`<button class="btn secondary" data-order-action="intervene" data-order="${o.id}" data-sub="${s.id}">${s.hold?'Liberar análise':'Colocar em análise'}</button>`:''}${role!=='admin'?`<button class="btn secondary" data-order-action="chat" data-order="${o.id}" data-sub="${s.id}">Chat do pedido</button>`:''}${role==='buyer'?orderDownloads(o,s):''}</div><div data-chat-slot="${s.id}"></div></section>`).join('')}</article>`).join(''):'<div class="order-empty"><h3>Nenhum pedido por aqui</h3><p>Adicione produtos à sacola e conclua o checkout demonstrativo para acompanhar a compra.</p></div>'}<p id="order-feedback" role="status"></p></div>`;
}
function bindOrderActions(root,role,refresh,catalog){
  root.onclick=async e=>{const b=e.target.closest('[data-order-action]');if(!b)return;e.preventDefault();const a=b.dataset.orderAction,orders=readDemoOrders(),o=orders.find(o=>o.id===b.dataset.order),s=o?.suborders.find(s=>s.id===b.dataset.sub&&(role!=='seller'||s.store===sellerContext()));
    try{if(!o||(role==='buyer'&&!ownsBuyerOrder(o)))throw Error('Pedido não encontrado nesta conta.');if(a==='pay'&&role==='buyer'){if(b.dataset.result==='paid')validateOrderStock(catalog,o.suborders.filter(s=>s.status!=='cancelled').flatMap(s=>s.items.map(i=>({id:i.id,qty:i.qty,selection:i.selection}))),orders,o.id);changeDemoPayment(o,b.dataset.result);saveDemoOrders(orders);refresh();return;}
      if(!s)throw Error('Subpedido não encontrado.');if(a==='intervene'&&role==='admin'){const reason=prompt('Motivo da intervenção:');if(!reason)return;s.hold=!s.hold;const event={...s,id:s.id+'-analise-'+Date.now(),history:[]};orderEvent(o,event,s.hold?'held':s.status);auditMarketplace('Pedido '+s.id+(s.hold?' em análise':' liberado'),reason);saveDemoOrders(orders);refresh();return;}if(a==='advance'&&role!=='buyer'){const reason=role==='admin'?prompt('Motivo da alteração administrativa:'):'Avanço pelo lojista';if(!reason)return;advanceDemoSuborder(o,s.id,s.store);auditMarketplace('Pedido '+s.id+' · '+statusLabel(s),reason,role==='admin'?'Administrador':'Loja '+s.store);saveDemoOrders(orders);refresh();return;}
      if(a==='download'&&role==='buyer'){const item=s.items.find(i=>i.id===Number(b.dataset.product)&&i.type==='virtual');if(o.payment!=='paid'||!item)throw Error('Download indisponível antes do pagamento.');const url=URL.createObjectURL(new Blob([`ARQUIVO DEMONSTRATIVO\n${item.name}\nPedido ${o.id}\n\nExemplo sem conteúdo comercial. Não inclui cursos ou aulas em vídeo.`],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='exemplo-download-digital.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
      if(a==='chat'&&role!=='admin'){const slot=root.querySelector(`[data-chat-slot="${s.id}"]`);slot.innerHTML=`<section class="order-chat"><h4>Conversa com ${role==='buyer'?orderEscape(s.storeName):'o comprador'}</h4><p>Vinculada a este pedido. Mensagens locais, sem notificações reais.</p><div class="chat-messages">${s.messages.length?s.messages.map(m=>`<div class="chat-message ${m.role===role?'mine':''}"><b>${m.role==='seller'?'Loja':'Comprador'}</b><small>${orderDate(m.at)}</small>${m.text?`<p>${orderEscape(m.text)}</p>`:''}${m.image&&/^data:image\/(png|jpeg|webp);base64,/.test(m.image)?`<img src="${m.image}" alt="Imagem enviada na conversa">`:''}</div>`).join(''):'<p>Nenhuma mensagem. Comece a conversa sobre seu pedido.</p>'}</div><form data-chat-order="${o.id}" data-chat-sub="${s.id}"><label class="field-label">Mensagem<textarea class="panel-input" name="message" maxlength="2000" placeholder="Escreva sobre este pedido"></textarea></label><label class="field-label">Imagem opcional (PNG, JPEG ou WEBP, até 5 MB)<input type="file" name="image" accept="image/png,image/jpeg,image/webp"></label><button class="btn">Enviar mensagem demonstrativa</button><p class="chat-feedback" role="status"></p></form></section>`;}
    }catch(err){root.querySelector('#order-feedback').textContent=err.message;}
  };
  root.onsubmit=async e=>{const f=e.target.closest('[data-chat-order]');if(!f)return;e.preventDefault();const feedback=f.querySelector('.chat-feedback');try{const text=f.elements.message.value.trim(),file=f.elements.image.files[0];if(!text&&!file)throw Error('Escreva uma mensagem ou escolha uma imagem.');if(file&&(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024))throw Error('Use PNG, JPEG ou WEBP de até 5 MB.');let image=null;if(file)image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Não foi possível ler a imagem.'));reader.readAsDataURL(file);});const orders=readDemoOrders(),o=orders.find(o=>o.id===f.dataset.chatOrder),s=o?.suborders.find(s=>s.id===f.dataset.chatSub&&(role!=='seller'||s.store===sellerContext()));if(!s||role==='admin'||(role==='buyer'&&!ownsBuyerOrder(o)))throw Error('Conversa não autorizada.');s.messages.push({role,text,image,at:new Date().toISOString()});saveDemoOrders(orders);const sub=s.id;refresh();root.querySelector(`[data-order-action="chat"][data-sub="${sub}"]`)?.click();}catch(err){feedback.textContent=err.message;}};
}
export function sellerOrderRows(role='seller',filters={}){
 return readDemoOrders().flatMap(o=>o.suborders.filter(s=>role==='admin'||s.store===sellerContext()).map(s=>({o,s}))).filter(({o,s})=>{
 const q=(filters.q||'').toLowerCase(),date=new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo'}).format(new Date(o.createdAt));
 return (!q||[o.id,s.id,o.buyerName,o.address?.name,...s.items.map(i=>i.name)].join(' ').toLowerCase().includes(q))&&(!filters.status?.length||filters.status.includes(s.status))&&(!filters.from||date>=filters.from)&&(!filters.to||date<=filters.to);
 }).sort((a,b)=>b.o.createdAt.localeCompare(a.o.createdAt));
}
export function sellerOrdersTable(role='seller',filters={},page=0){const all=sellerOrderRows(role,filters),rows=all.slice(page*20,page*20+20);return `<p>${all.length} pedido(s) · Total filtrado: ${orderMoney(all.reduce((n,{s})=>n+s.total,0))}</p><div class="portal-table"><table><thead><tr><th>Pedido</th><th>Data</th><th>Cliente</th><th>Itens</th><th>Pagamento</th><th>Modalidade</th><th>Situação</th><th>Total</th><th>Ação</th></tr></thead><tbody>${rows.map(({o,s})=>`<tr><td><b>${orderEscape(s.id)}</b>${o.demoData?'<small>Fictício</small>':''}</td><td>${orderDate(o.createdAt)}</td><td>${orderEscape(o.buyerName||o.address?.name||'Comprador')}</td><td>${s.items.reduce((n,i)=>n+i.qty,0)}</td><td>${orderEscape(ORDER_STATUS[o.payment])}</td><td>${methodLabel(s.method)}</td><td><span class="type-pill">${statusLabel(s)}</span></td><td>${orderMoney(s.total)}</td><td><button class="text-link" data-open-order="${orderEscape(o.id)}">Ver detalhes</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?'<p>Nenhum pedido corresponde aos filtros.</p>':''}<div class="editor-actions"><button class="btn secondary" data-page="${page-1}" ${page===0?'disabled':''}>Anterior</button><span>Página ${page+1} de ${Math.max(1,Math.ceil(all.length/20))}</span><button class="btn secondary" data-page="${page+1}" ${(page+1)*20>=all.length?'disabled':''}>Próxima</button></div>`;}
export function mountOrderPanel(role,pageName='pedidos'){
 const root=document.querySelector('#order-panel');if(!root)return;
 let filters={q:'',status:[],from:'',to:''},page=0,detail=null,conversation=null;
 function refresh(){
  if(pageName==='chat'&&role==='seller'){
   const rows=sellerOrderRows(role),chosen=rows.find(({s})=>s.id===conversation)||rows[0];conversation=chosen?.s.id;
   root.innerHTML=`<section class="portal-panel"><h2>Conversas pós-compra</h2><p>Selecione um pedido para conversar com o comprador. Mensagens salvas somente neste navegador.</p><div class="seller-chat-layout"><nav aria-label="Conversas">${rows.map(({o,s})=>`<button class="conversation-row ${s.id===conversation?'selected':''}" data-conversation="${orderEscape(s.id)}"><b>${orderEscape(o.buyerName||o.address?.name||'Comprador')}</b><small>${orderEscape(s.id)} · ${statusLabel(s)}</small><span>${orderEscape(s.messages.at(-1)?.text||'Iniciar conversa sobre este pedido')}</span></button>`).join('')||'<p>Nenhuma conversa disponível.</p>'}</nav><div>${chosen?`<h3>${orderEscape(chosen.o.buyerName||'Comprador')}</h3><p>Pedido ${orderEscape(chosen.s.id)}</p><button hidden data-order-action="chat" data-order="${orderEscape(chosen.o.id)}" data-sub="${orderEscape(chosen.s.id)}"></button><div data-chat-slot="${orderEscape(chosen.s.id)}"></div>`:'Selecione uma conversa.'}</div></div><p id="order-feedback" role="status"></p></section>`;
  }else if(detail)root.innerHTML='<button class="btn secondary" data-order-list>← Voltar à lista de pedidos</button>'+ordersMarkup(role,detail);
  else root.innerHTML=`<section class="portal-panel"><h2>Pedidos de venda</h2><form id="seller-order-filters" class="seller-order-filters"><label class="field-label">Buscar pedido, cliente ou produto<input class="panel-input" name="q" value="${orderEscape(filters.q)}"></label><label class="field-label">De<input class="panel-input" type="date" name="from" value="${filters.from}"></label><label class="field-label">Até<input class="panel-input" type="date" name="to" value="${filters.to}"></label><label class="field-label">Situações (selecione uma ou mais)<select class="panel-input" name="status" multiple size="3">${Object.entries(ORDER_STATUS).filter(([v])=>!['failed','held'].includes(v)).map(([v,label])=>`<option value="${v}" ${filters.status.includes(v)?'selected':''}>${label}</option>`).join('')}</select></label><button class="btn">Filtrar</button><button class="btn secondary" type="button" data-clear-filters>Limpar</button></form>${sellerOrdersTable(role,filters,page)}</section>`;
  bindOrderActions(root,role,refresh);const actions=root.onclick,submit=root.onsubmit;
  root.onclick=e=>{const b=e.target.closest('[data-open-order],[data-order-list],[data-conversation],[data-page],[data-clear-filters]');if(!b)return actions(e);if(b.hasAttribute('data-open-order'))detail=b.dataset.openOrder;if(b.hasAttribute('data-order-list'))detail=null;if(b.hasAttribute('data-conversation'))conversation=b.dataset.conversation;if(b.hasAttribute('data-page'))page=Number(b.dataset.page);if(b.hasAttribute('data-clear-filters')){filters={q:'',status:[],from:'',to:''};page=0;}refresh();};
  root.onsubmit=e=>{if(e.target.id!=='seller-order-filters')return submit(e);e.preventDefault();const data=new FormData(e.target);filters={q:String(data.get('q')),from:String(data.get('from')),to:String(data.get('to')),status:data.getAll('status')};page=0;refresh();};
  if(pageName==='chat'&&role==='seller')root.querySelector('[data-order-action="chat"]')?.click();
 }
 refresh();
}
export function createOrderJourney({products,lines,modal,syncCart,showCart}){
  const accountUI=createBuyerAccountUI({modal,onOrders:()=>showOrders(),onLogout:()=>{lines.clear();syncCart()}});
  function showOrders(detailId=null){if(!currentBuyer()){accountUI.auth('login',()=>showOrders(detailId));return}modal('Minha conta · Pedidos e downloads','<div id="buyer-orders"></div>');const root=document.querySelector('#buyer-orders'),refresh=()=>{root.innerHTML=ordersMarkup('buyer',detailId)};refresh();bindOrderActions(root,'buyer',refresh,products);root.addEventListener('click',e=>{const b=e.target.closest('[data-buyer-detail],[data-buyer-reorder],[data-buyer-account]');if(!b)return;e.preventDefault();e.stopPropagation();if(b.hasAttribute('data-buyer-account')){accountUI.account();return}if(b.hasAttribute('data-buyer-detail')){showOrders(b.dataset.buyerDetail||null);return}try{const orders=readDemoOrders(),o=orders.find(o=>o.id===b.dataset.buyerReorder&&ownsBuyerOrder(o));if(!o)throw Error('Pedido não encontrado nesta conta.');const result=reorderLines(products,[...lines.values()],o,orders);lines.clear();result.forEach(l=>lines.set(l.id+'-'+encodeURIComponent(JSON.stringify(l.selection)),l));syncCart();showCart();}catch(err){root.querySelector('#order-feedback').textContent=err.message}});}
  function checkout(){if(!lines.size)return;if(!currentBuyer()){accountUI.auth('login',checkout);return}const buyer=currentBuyer();const cart=[...lines.values()],storeIds=[...new Set(cart.map(l=>products[l.id].store))];let reviewed=null;
    modal('Finalizar compra',`<div class="checkout-flow"><div class="checkout-progress"><b>1. Entrega</b><span>2. Revisão</span><span>3. Pagamento</span></div><p class="order-notice">Compra demonstrativa. Use dados fictícios. Não há cobrança, consulta de CEP ou cálculo real de rotas.</p><form id="checkout-form"><div class="checkout-address-picker"><label class="field-label">Endereço de entrega salvo<select class="panel-input" name="savedDelivery"><option value="">Preencher manualmente</option>${buyer.addresses.map(a=>`<option value="${a.id}" ${a.id===buyer.defaultDelivery?'selected':''}>${orderEscape(a.label)} · ${orderEscape(a.street)}</option>`).join('')}</select></label><label class="field-label">Endereço de cobrança<select class="panel-input" name="savedBilling"><option value="">Mesmo endereço informado para entrega</option>${buyer.addresses.map(a=>`<option value="${a.id}" ${a.id===buyer.defaultBilling?'selected':''}>${orderEscape(a.label)} · ${orderEscape(a.street)}</option>`).join('')}</select></label></div><section id="checkout-address"><h3>Seus dados e região</h3><p>O CEP define as lojas da sua cidade disponíveis para retirada, sem limite de distância.</p><div class="form-two"><label class="field-label">Nome do destinatário<input class="panel-input" name="name" maxlength="100" value="Cliente de demonstração"></label><label class="field-label">CEP<input class="panel-input" name="cep" maxlength="9" placeholder="00000-000"></label><label class="field-label">Rua<input class="panel-input" name="street" maxlength="150" placeholder="Rua Exemplo"></label><label class="field-label">Número<input class="panel-input" name="number" maxlength="20" placeholder="123"></label><label class="field-label">Cidade<input class="panel-input" name="city" maxlength="100"></label><label class="field-label">Complemento<input class="panel-input" name="complement" maxlength="100" placeholder="Opcional"></label></div></section><h3>Uma escolha para cada loja</h3>${storeIds.map(id=>{const store=readMarketplace().stores.find(s=>s.id===id)||ORDER_STORES[id],physical=cart.some(l=>products[l.id].store===id&&products[l.id].type!=='virtual');return `<fieldset class="checkout-store"><legend>${orderEscape(store.name)} · ${orderEscape(store.city)}</legend>${physical?`<label class="field-label">Recebimento · ${store.name}<select class="panel-input" name="method-${id}"><option value="pickup">Retirada na loja · grátis</option><option value="delivery">Entrega pela loja · ${orderMoney(store.rate)}/km</option></select></label><label class="field-label" data-distance="${id}" hidden>Distância pelas ruas, em km (simulada)<input class="panel-input" name="km-${id}" disabled type="number" min="0.01" max="${store.maxKm}" step="0.01" value="${store.routeKm??3.4}"></label><p>Retirada: ${orderEscape(establishmentAddress(store))}. Entrega demonstrativa somente em ${store.city}, até ${store.maxKm} km.</p>`:'<p>Somente arquivos digitais. Sem frete ou retirada; download após pagamento confirmado.</p>'}</fieldset>`}).join('')}<div class="form-two"><label class="field-label">E-mail demonstrativo<input class="panel-input" name="email" type="email" required placeholder="cliente@example.com"></label><label class="field-label">WhatsApp demonstrativo<input class="panel-input" name="whatsapp" required pattern="[0-9]{10,13}" placeholder="44999990000"></label><label class="field-label">Cupom<input class="panel-input" name="coupon" maxlength="20"></label></div><h3>Como prefere pagar?</h3><label class="field-label">Forma de pagamento<select class="panel-input" name="payment">${readMarketplace().pix?'<option value="pix">Pix · simulação</option>':''}${readMarketplace().card?'<option value="card">Cartão de crédito · simulação</option>':''}</select></label><p class="catalog-help">Não informe números de cartão, CPF ou dados bancários.</p><button class="btn" type="submit">Revisar compra →</button><p id="checkout-feedback" role="status"></p></form><div id="checkout-review"></div></div>`);
    const f=document.querySelector('#checkout-form'),review=document.querySelector('#checkout-review');
    const fillAddress=a=>{for(const k of ['name','cep','street','number','city','complement'])if(f.elements[k])f.elements[k].value=a?.[k]||'';};const location=readDeliveryLocation(),selectedAddress=buyer.addresses.find(a=>a.cep===location?.cep&&a.id===buyer.defaultDelivery)||buyer.addresses.find(a=>a.cep===location?.cep);fillAddress(selectedAddress);f.elements.savedDelivery.value=selectedAddress?.id||'';if(location){f.elements.cep.value=location.cep;f.elements.city.value=location.city;}f.elements.name.value||=buyer.name;f.elements.cep.value||=localStorage.getItem('temlogoali.buyer-cep')||'';f.elements.email.value=buyer.email;f.elements.whatsapp.value=buyer.phone;f.elements.savedDelivery.addEventListener('change',()=>fillAddress(buyer.addresses.find(a=>a.id===f.elements.savedDelivery.value)));f.querySelectorAll('[data-distance]').forEach(el=>el.style.display='none');
    function refreshCheckoutShipping(){for(const id of storeIds){const select=f.elements['method-'+id];if(!select)continue;let q=null;try{const subtotal=cart.filter(l=>products[l.id].store===id).reduce((sum,l)=>sum+resolveSelection(products,products[l.id],l.selection,l.qty).totalCents,0);q=localFreightQuote(id,f.elements.cep.value,subtotal);}catch{}const delivery=select.querySelector('[value=delivery]'),pickup=select.querySelector('[value=pickup]');delivery.disabled=!q?.delivery;pickup.disabled=!q?.pickup;delivery.textContent=q?.delivery?'Entrega pela loja · '+(q.freight===0?'Frete grátis':orderMoney(q.freight))+' · cerca de '+q.minutes+' min após saída':'Entrega não disponível para este CEP';pickup.textContent=q?.pickup?'Retirada na loja · grátis':'Retirada não disponível para este CEP';if(select.selectedOptions[0]?.disabled)select.value=q?.delivery?'delivery':q?.pickup?'pickup':'';}}
    refreshCheckoutShipping();
    f.onchange=()=>{reviewed=null;review.innerHTML='';refreshCheckoutShipping();storeIds.forEach(id=>{const field=f.querySelector(`[data-distance="${id}"]`);if(field){field.hidden=f.elements['method-'+id].value!=='delivery';f.elements['km-'+id].disabled=field.hidden;}});};f.oninput=()=>{reviewed=null;review.innerHTML='';refreshCheckoutShipping()};
    f.onsubmit=e=>{e.preventDefault();try{const data=new FormData(f),address=Object.fromEntries(['name','cep','street','number','city','complement','email','whatsapp'].map(k=>[k,String(data.get(k)||'').trim()])),delivery=Object.fromEntries(storeIds.map(id=>[id,{method:data.get('method-'+id)||'digital',km:data.get('method-'+id)==='delivery'?localFreightQuote(id,address.cep).km:0,city:address.city,cep:address.cep,coupon:data.get('coupon')}]));const o=createDemoOrder(products,cart,delivery,address,data.get('payment'),readDemoOrders());reviewed={delivery,address,billingAddress:structuredClone(buyer.addresses.find(a=>a.id===data.get('savedBilling'))||address),payment:data.get('payment')};document.querySelector('#checkout-feedback').textContent='';review.innerHTML=`<section class="checkout-review"><span class="eyebrow">REVISE SUA COMPRA</span><h3>${o.suborders.length} loja(s), um checkout</h3>${o.suborders.map(s=>`<section class="checkout-store"><h4>${s.storeName}</h4>${orderItems(s.items)}${orderSummary(s)}</section>`).join('')}<div class="grand-total"><span>Total a pagar</span><strong>${orderMoney(o.total)}</strong></div><p>Pagamento: ${o.paymentMethod==='pix'?'Pix':'Cartão de crédito'}. O frete é repassado integralmente à loja; a comissão incide apenas nos produtos. Percentual e taxas ainda serão definidos.</p><button class="btn" type="button" id="place-demo-order">Criar pedido demonstrativo →</button><p id="place-order-feedback" role="status"></p></section>`;review.querySelector('#place-demo-order').onclick=()=>{if(!reviewed)return;try{const orders=readDemoOrders(),order=createDemoOrder(products,cart,reviewed.delivery,reviewed.address,reviewed.payment,orders);if(!currentBuyer()||currentBuyer().id!==buyer.id)throw Error('Entre novamente para finalizar esta compra.');order.buyerId=buyer.id;order.buyerName=buyer.name;order.billingAddress=structuredClone(reviewed.billingAddress);order.deliveryAddress=structuredClone(reviewed.address);saveDemoOrders([...orders,order]);reviewed=null;lines.clear();syncCart();showOrders(order.id);}catch(err){document.querySelector('#place-order-feedback').textContent=err.message;}};review.scrollIntoView({block:'start',behavior:'smooth'});}catch(err){document.querySelector('#checkout-feedback').textContent=err.message;}};
  }
  document.addEventListener('click',e=>{const b=e.target.closest('[data-checkout],[data-action="account"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.hasAttribute('data-checkout'))checkout();else accountUI.account();},true);
  return {checkout,showOrders};
}



